const map=new Map(scene.instances.map(i=>[i.name,{...i,hidden:false,getX(){return this.x},getY(){return this.y},getWidth(){return this.width},getHeight(){return this.height},setPosition(x,y){this.x=x;this.y=y},setWidth(w){this.width=w},setHeight(h){this.height=h},hide(v=true){this.hidden=v},setOpacity(v){this.opacity=v},setString(v){this.string=v},setColor(v){this.color=v},setCharacterSize(v){this.characterSize=v},setAnimation(v){this.animation=v},setZOrder(v){this.zOrder=v},setAngle(v){this.angle=v}}]));
const tileCopies=scene.instances.filter(i=>i.name==='DigTiles').map(i=>({...map.get('DigTiles'),...i}));assert.equal(tileCopies.length,207);const buildCopies=scene.instances.filter(i=>i.name==='ConstructionCells').map(i=>({...map.get('ConstructionCells'),...i}));assert.equal(buildCopies.length,60);const expTileCopies=scene.instances.filter(i=>i.name==='ExpTiles').map(i=>({...map.get('ExpTiles'),...i}));const runtimeScene={getObjects:n=>n==='ExpTiles'?expTileCopies:n==='DigTiles'?tileCopies:n==='ConstructionCells'?buildCopies:[map.get(n)]};let cursor={x:0,y:0},release=false,held=false,keys=new Set();
const gdjs={evtTools:{input:{touchSimulateMouse(){},isKeyPressed:(s,k)=>keys.has(k),getCursorX:()=>cursor.x,getCursorY:()=>cursor.y,isMouseButtonReleased:()=>release,isMouseButtonPressed:()=>held},runtimeScene:{getElapsedTimeInSeconds:()=>.05}}};
const run=Function('runtimeScene','gdjs',scene.events.find(e=>e.inlineCode).inlineCode.join('\n'));const frame=()=>run(runtimeScene,gdjs);
const tick=n=>{for(let i=0;i<n;i++)frame()};
